('Kawasaki Ninja ZX-10R','kawasaki-ninja-zx-10r','Kawasaki',(SELECT id FROM cat WHERE slug='motorcycles'),'Track-bred superbike for the street.','Kawasaki Ninja ZX-10R with 998cc inline-four, 200hp, and race-derived electronics.',18500.00,19900.00,'Brand New',2,4.8,15,3,ARRAY['https://images.pexels.com/photos/26551186/pexels-photo-26551186.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],true,false,true,false,'2 Year Kawasaki Warranty','Pickup or nationwide delivery'),
('Honda CBR500R (Pre-owned)','honda-cbr500r-preowned','Honda',(SELECT id FROM cat WHERE slug='motorcycles'),'Certified pre-owned sport bike.','Professionally inspected Honda CBR500R with 12,000km, 471cc parallel-twin, and full service.',5500.00,7200.00,'Very Good',3,4.5,9,5,ARRAY['https://images.pexels.com/photos/33203538/pexels-photo-33203538.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],false,false,false,false,'3 Month Declutter Warranty','Pickup or nationwide delivery'),
('USB-C Fast Charger 65W','usb-c-fast-charger-65w','Anker',(SELECT id FROM cat WHERE slug='accessories'),'GaN II technology, compact power.','Anker 65W USB-C charger with GaN II tech, PowerIQ 3.0, and dual-port charging.',39.00,49.00,'Brand New',80,4.6,54,92,ARRAY['https://images.pexels.com/photos/4195332/pexels-photo-4195332.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/4387770/pexels-photo-4387770.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],false,false,true,true,'18 Month Anker Warranty','Free delivery in 2-3 business days'),
('Braided USB-C Cable 2m','braided-usb-c-cable-2m','Anker',(SELECT id FROM cat WHERE slug='accessories'),'Durable, fast, and tangle-free.','Anker nylon-braided USB-C to USB-C cable, 100W PD support, 2-meter length.',19.00,25.00,'Brand New',100,4.5,38,65,ARRAY['https://images.pexels.com/photos/4072683/pexels-photo-4072683.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],false,false,false,false,'18 Month Anker Warranty','Free delivery in 2-3 business days')
) AS t(name, slug, brand, category_id, short_description, description, price, compare_at_price, condition, stock, rating, review_count, sales_count, images, is_featured, is_flash_deal, is_new_arrival, is_best_seller, warranty, delivery_info)
