-- Product specs
INSERT INTO public.product_specs (product_id, spec_key, spec_value, sort_order)
SELECT p.id, k, v, s FROM public.products p
JOIN (VALUES
  ('iphone-15-pro-max-256gb','Display','6.7" Super Retina XDR OLED',1),('iphone-15-pro-max-256gb','Chip','A17 Pro',2),('iphone-15-pro-max-256gb','Storage','256GB',3),('iphone-15-pro-max-256gb','Camera','48MP Main + 12MP Ultra Wide + 12MP Telephoto',4),('iphone-15-pro-max-256gb','Battery','Up to 29 hours video playback',5),('iphone-15-pro-max-256gb','Connectivity','5G, Wi-Fi 6E, Bluetooth 5.3, USB-C',6),('iphone-15-pro-max-256gb','Weight','221g',7),
  ('macbook-pro-14-m3-pro','Display','14.2" Liquid Retina XDR',1),('macbook-pro-14-m3-pro','Chip','M3 Pro',2),('macbook-pro-14-m3-pro','Memory','18GB unified',3),('macbook-pro-14-m3-pro','Storage','512GB SSD',4),('macbook-pro-14-m3-pro','Battery','Up to 18 hours',5),('macbook-pro-14-m3-pro','Ports','3x Thunderbolt 4, HDMI, SDXC, MagSafe 3',6),('macbook-pro-14-m3-pro','Weight','1.61kg',7),
  ('samsung-55-qled-4k-tv','Display','55" QLED 4K UHD',1),('samsung-55-qled-4k-tv','Resolution','3840 x 2160',2),('samsung-55-qled-4k-tv','HDR','Quantum HDR+',3),('samsung-55-qled-4k-tv','Smart OS','Tizen',4),('samsung-55-qled-4k-tv','HDMI','3 ports',5),
  ('playstation-5-slim','CPU','AMD Zen 2, 8 cores',1),('playstation-5-slim','GPU','AMD RDNA 2, 10.28 TFLOPs',2),('playstation-5-slim','Storage','1TB SSD',3),('playstation-5-slim','Resolution','Up to 4K 120fps',4),('playstation-5-slim','Controller','DualSense',5)
) AS x(slug, k, v, s) ON p.slug = x.slug
ON CONFLICT DO NOTHING;

